public static String eval(int[] guess,  
                          int[] ans){ 
  int w = 0; 
  int b = 0; 
  boolean go; 
  int j; 

  for(int i = 0; i < guess.length; i++){ 
    if( guess[i] == ans[i] ){ 
      b++; 
      <*1> 
    } 
  }     

  for(int i = 0; i < guess.length; i++){ 
    go = guess[i] != -1; 
    j = i + 1; 
    while( go && j < ans.length){ 
      if( guess[i] == ans[j] ){ 
        go = false; 
        w++; 
        guess[i] = -1; 
        ans[j] = -1; 
      } 
      j++; 
    } 
  } 

  return b + "_" + w; 
}

